const savedOrderIds=()=>JSON.parse(localStorage.getItem('yc_orders')||'[]') as string[]; const saveCart=()=>localStorage.setItem('yc_cart',JSON.stringify(cart)); const saveOrderId=(id:string)=>{const ids=[...new Set([...savedOrderIds(),id])];localStorage.setItem('yc_orders',JSON.stringify(ids));};
async function loadMyOrders(){const target=document.querySelector('#order-list');if(!target)return;if(!customerProfile){target.innerHTML='<p>Sign in to see your orders.</p><a class="account-link" href="/login?next=%2Forders">Sign in</a>';return}try{const results=await api<Order[]>('/customer/orders');target.innerHTML=results.map(o=>`<article class="invoice"><div><div><b>Invoice / Order ${orderCode(o.id)}</b><small class="order-date">${dateText(o.createdAt)}</small></div><span class="order-status">${esc(o.status)}</span></div>${timeline(o.status)}<p>${o.items.map(i=>`${esc(product(i.tone)?.name||i.tone)} · ${esc(product(i.tone)?.prices[i.variant]?.label||'Variant')} × ${i.quantity}`).join('<br>')}</p><p>${esc(o.customer)} · ${esc(o.address||'')}</p><strong>Total ${money(Number(o.total))}</strong>${!['Shipped','Delivered','Cancelled'].includes(o.status)?`<button data-cancel-order="${o.id}">Cancel order</button>`:''}</article>`).join('')||'<p>No orders yet.</p>';document.querySelectorAll<HTMLButtonElement>('[data-cancel-order]').forEach(b=>b.onclick=()=>confirmModal('Cancel this order?',async()=>{await api(`/orders/${b.dataset.cancelOrder}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:'cancel',message:'Customer requested cancellation'})});await loadMyOrders()}))}catch(error){target.textContent=(error as Error).message}}
const money=(n:number)=>`${n.toLocaleString()} Ks`; const amount=(s:string)=>Number(s.replace(/[^0-9]/g,'')); const product=(t:string)=>products.find(p=>p.tone===t)!; const total=()=>cart.reduce((n,i)=>n+amount(product(i.tone).prices[i.variant].price)*i.quantity,0); const esc=(s:string)=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]!); const image=(s:string)=>{const aliases:{[key:string]:string}={'chocobrown-1.png':'product-stocking-chocobrown.png','magicblack-1.jpg':'product-stocking-magicblack-1.jpg','skincolor-1.png':'product-stocking-skincolor-1.png'};const key=aliases[s.replace(/^\/products\//,'').replace(/^\//,'')]??decodeURIComponent(s.replace(/^\/products\//,'').replace(/^\//,''));return s.startsWith('https://')||s.startsWith('data:')?s:`/${key.split('/').map(encodeURIComponent).join('/')}`}; const adminRoute=()=>location.pathname.replace(/\/+$/,'')==='/admin'; const developerRoute=()=>location.pathname.replace(/\/+$/,'')==='/developer';
const dateText=(value?:string)=>value?new Date(value).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'}):'Date unavailable'; const dateKey=(value?:string)=>value?new Date(value).toLocaleDateString('en-CA'):'';
const orderCode=(id:number|string)=>`yc-${1000+Number(id)}`; const orderSteps=['Pending','Confirmed','Shipped','Delivered']; const timeline=(status:string)=>`<div class="order-timeline">${orderSteps.map((step,i)=>`<div class="timeline-step ${status===step?'current':''} ${orderSteps.indexOf(status)>i?'done':''}"><span>${orderSteps.indexOf(status)>i?'✓':i+1}</span><small>${step}</small></div>`).join('')}</div>`;
async function api<T>(path:string,options?:RequestInit):Promise<T>{const r=await fetch(API+path,{credentials:'same-origin',...options});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d as T}
function notify(message:string){const old=document.querySelector('.toast');old?.remove();const toast=document.createElement('div');toast.className='toast';toast.textContent=message;document.body.append(toast);setTimeout(()=>toast.remove(),2600)}
function invoiceModal(id:string,customer:string,phone:string,address:string,items:Item[],orderTotal:number){const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<section class="invoice-modal"><button class="modal-close">×</button><small>ORDER CONFIRMATION</small><h2>Thanks for shopping with us</h2><div class="invoice-number"><b>${orderCode(id)}</b><br>${esc(customer)} · ${esc(phone)}<br>${esc(address)}</div><div class="invoice-lines">${items.map(i=>`<div>${esc(product(i.tone).name)} · ${esc(product(i.tone).prices[i.variant].label)} × ${i.quantity}</div>`).join('')}</div><strong class="invoice-total">Total ${money(orderTotal)}</strong><button class="modal-primary" data-close-modal>View my orders</button></section>`;document.body.append(modal);modal.querySelector('.modal-close')?.addEventListener('click',()=>modal.remove());modal.querySelector('[data-close-modal]')?.addEventListener('click',()=>{location.href='/orders'})}
function confirmModal(message:string,action:()=>Promise<void>){const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<section class="confirm-modal"><h2>Confirm request</h2><p>${esc(message)}</p><div><button class="modal-secondary" data-close>Keep order</button><button class="modal-primary" data-confirm>Confirm cancellation</button></div></section>`;document.body.append(modal);modal.querySelector('[data-close]')?.addEventListener('click',()=>modal.remove());modal.querySelector('[data-confirm]')?.addEventListener('click',async()=>{await action();modal.remove()})}
function render(){const detail=location.pathname.startsWith('/product/'),route=location.pathname,cartCount=cart.reduce((n,i)=>n+i.quantity,0),profileHref=customerProfile?'/profile':'/login',profileLabel=customerProfile?'Profile':'Login / Sign up',showGuide=localStorage.getItem('yc_mobile_guide_seen')!=='1';document.querySelector('#app')!.innerHTML=developerRoute()?(isDeveloper?developer():developerLogin()):adminRoute()?(isAdmin?admin():login()):`<div class="store-shell"><header><a class="brand" href="/"><span class="logo">Yours CayCi</span><small>STOCKINGS</small></a><nav><a href="/">Shop</a><a class="cart-link" href="/cart" aria-label="Cart"><span class="cart-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M4 5h2l1.5 11h10L20 8H7"></path><circle cx="10" cy="20" r=".8"></circle><circle cx="17" cy="20" r=".8"></circle></svg>${cartCount?`<b class="cart-badge">${cartCount}</b>`:''}</span><span class="cart-label">Cart</span></a><a href="/orders">My Orders</a><a href="${profileHref}">${customerProfile?'Profile':'Sign in'}</a></nav><a class="profile-float" href="${profileHref}" aria-label="${profileLabel}"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="3.5"></circle><path d="M5 20c.8-3.5 3.2-5.3 7-5.3s6.2 1.8 7 5.3"></path></svg><span>${profileLabel}</span></a></header>${detail?detailPage():route==='/cart'?cartPage():route==='/orders'?ordersPage():route==='/login'||route==='/signup'||route==='/signup/delivery'?authPage(route):route==='/profile'?profilePage():shop()}<nav class="mobile-dock" aria-label="Mobile navigation"><a class="${route==='/'?'active':''}" href="/"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 10 8-6 8 6v9H4z"></path></svg><span>Shop</span></a><a class="${route==='/orders'?'active':''}" href="/orders"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 4h10v16H7zM9 8h6M9 12h6M9 16h4"></path></svg><span>My Orders</span></a><a class="${route==='/cart'?'active':''}" href="/cart"><span class="cart-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M4 5h2l1.5 11h10L20 8H7"></path><circle cx="10" cy="20" r=".8"></circle><circle cx="17" cy="20" r=".8"></circle></svg>${cartCount?`<b class="cart-badge">${cartCount}</b>`:''}</span><span>Cart</span></a></nav>${showGuide?'<aside class="mobile-guide" role="note"><button type="button" id="dismiss-mobile-guide" aria-label="Dismiss guide">×</button><b>Quick guide</b><span>Use this dock to shop, view orders, and open your cart.</span><i aria-hidden="true"></i></aside>':''}<footer class="site-footer"><span>@yourscayci2026</span><a href="https://pockraft.asia" target="_blank" rel="noreferrer">Developed by Pockraft</a></footer></div>`;bind();bindStatusSelects();bindOrderTools();bindSaveIndicators();bindNewProductPanel();bindUploadInputs();bindImageManagers();applyCoverViews();bindQuickAdd();bindDetail();bindCustomerForms();bindDeveloper();document.querySelector('#dismiss-mobile-guide')?.addEventListener('click',()=>{localStorage.setItem('yc_mobile_guide_seen','1');document.querySelector('.mobile-guide')?.remove()});if(!adminRoute()&&!developerRoute())loadMyOrders();}
function bindLocaleToggle(){const header=document.querySelector('header');if(!header||document.querySelector('.locale-toggle'))return;const toggle=document.createElement('div');toggle.className=`locale-toggle${location.pathname==='/profile'?' profile-locale':''}`;toggle.setAttribute('aria-label','Language');toggle.innerHTML='<button type="button" data-locale="en">EN</button><button type="button" data-locale="mm">MM</button>';const target=location.pathname==='/profile'?document.querySelector('.account-card'):window.matchMedia('(max-width:640px)').matches?document.querySelector('.store-shell'):header;(target||header).append(toggle);toggle.querySelectorAll<HTMLButtonElement>('[data-locale]').forEach(button=>button.onclick=()=>{locale=button.dataset.locale==='mm'?'mm':'en';localStorage.setItem('yc_locale',locale);render()});applyLocale()}
async function loadBanner(){try{const result=await api<{desktop:string|null;mobile:string|null;desktopView?:BannerView;mobileView?:BannerView}>('/store/banner');const nextDesktop=result.desktop||'',nextMobile=result.mobile||'';bannerDesktopView=result.desktopView||bannerDesktopView;bannerMobileView=result.mobileView||bannerMobileView;if(nextDesktop!==bannerDesktop||nextMobile!==bannerMobile){bannerDesktop=nextDesktop;bannerMobile=nextMobile;render()}}catch{} }
function ensureBannerEditor(){const settingsForm=document.querySelector<HTMLFormElement>('#change-pass');if(!settingsForm||document.querySelector('#store-banner'))return;const section=document.createElement('section');section.className='admin-section banner-admin';section.innerHTML=`<h2>Shop banner</h2><p class="muted">Upload one banner, then drag and zoom it separately inside the desktop and mobile frames.</p><form id="store-banner"><div class="banner-admin-grid"><label><span>Banner image</span><input name="desktopBanner" type="file" accept="image/png,image/jpeg,image/webp"><small class="muted">The same image is used for both views.</small></label><label><span>Desktop preview</span><div class="banner-admin-preview desktop-frame"><img data-banner-preview="desktop" src="${bannerDesktop||image(products[0]?.images[0]||'')}" alt="Desktop banner"></div><div class="banner-view-controls"><select name="desktopFit"><option value="cover">Fill frame</option><option value="contain">Show full image</option></select><select name="desktopPosition"><option value="top">Top</option><option value="center">Center</option><option value="bottom">Bottom</option></select><label>Zoom <output data-zoom="desktop">100%</output><input name="desktopZoom" type="range" min="100" max="180" step="5" value="${bannerDesktopView.zoom}"></label></div></label><label><span>Mobile preview</span><div class="banner-admin-preview mobile-frame"><img data-banner-preview="mobile" src="${bannerMobile||bannerDesktop||image(products[0]?.images[0]||'')}" alt="Mobile banner"></div><div class="banner-view-controls"><select name="mobileFit"><option value="cover">Fill frame</option><option value="contain">Show full image</option></select><select name="mobilePosition"><option value="top">Top</option><option value="center">Center</option><option value="bottom">Bottom</option></select><label>Zoom <output data-zoom="mobile">100%</output><input name="mobileZoom" type="range" min="100" max="180" step="5" value="${bannerMobileView.zoom}"></label></div></label></div><button type="submit">Save banner views</button></form>`;settingsForm.parentElement?.before(section);bindBannerEditor()}
function bindBannerEditor(){const form=document.querySelector<HTMLFormElement>('#store-banner');if(!form||form.dataset.bound)return;form.dataset.bound='true';const desktopInput=form.querySelector<HTMLInputElement>('input[name="desktopBanner"]')!,save=form.querySelector<HTMLButtonElement>('button[type="submit"]')!;const preview=(name:'desktop'|'mobile')=>form.querySelector<HTMLImageElement>(`[data-banner-preview="${name}"]`)!;const state:{desktop:BannerView;mobile:BannerView}={desktop:{...bannerDesktopView},mobile:{...bannerMobileView}};const update=(name:'desktop'|'mobile')=>{const current=state[name],target=preview(name);target.style.objectFit=current.fit;target.style.objectPosition=`${current.x}% ${current.y}%`;target.style.transform=`scale(${current.zoom/100})`;form.querySelector<HTMLOutputElement>(`[data-zoom="${name}"]`)!.value=`${current.zoom}%`};const previewFile=(file:File)=>{const url=URL.createObjectURL(file);preview('desktop').src=url;preview('mobile').src=url;save.disabled=false};const optimize=(source:File|string)=>new Promise<string>((resolve,reject)=>{const url=source instanceof File?URL.createObjectURL(source):source;const imageElement=new Image();imageElement.onload=()=>{const max=1800,scale=Math.min(1,max/imageElement.width,max/imageElement.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(imageElement.width*scale));canvas.height=Math.max(1,Math.round(imageElement.height*scale));canvas.getContext('2d')!.drawImage(imageElement,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>{if(!blob){reject(new Error('Could not optimize banner image'));return}const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(blob)},'image/jpeg',.82)};imageElement.onerror=()=>reject(new Error('Could not read banner image'));imageElement.src=url});const bindDrag=(name:'desktop'|'mobile')=>{const frame=preview(name).parentElement!;let startX=0,startY=0,startPX=50,startPY=50;frame.onpointerdown=event=>{event.preventDefault();frame.setPointerCapture(event.pointerId);startX=event.clientX;startY=event.clientY;startPX=state[name].x;startPY=state[name].y;frame.classList.add('dragging')};frame.onpointermove=event=>{if(!frame.hasPointerCapture(event.pointerId))return;const rect=frame.getBoundingClientRect();state[name].x=Math.min(100,Math.max(0,startPX-(event.clientX-startX)/rect.width*100));state[name].y=Math.min(100,Math.max(0,startPY-(event.clientY-startY)/rect.height*100));update(name)};const stop=(event:PointerEvent)=>{if(frame.hasPointerCapture(event.pointerId))frame.releasePointerCapture(event.pointerId);frame.classList.remove('dragging')};frame.onpointerup=stop;frame.onpointercancel=stop;frame.onwheel=event=>{event.preventDefault();state[name].zoom=Math.min(180,Math.max(100,state[name].zoom+(event.deltaY<0?5:-5)));form.querySelector<HTMLInputElement>(`[name="${name}Zoom"]`)!.value=String(state[name].zoom);update(name)}};desktopInput.onchange=()=>{const file=desktopInput.files?.[0];if(file)previewFile(file)};(['desktop','mobile'] as const).forEach(name=>{const prefix=name==='desktop'?'desktop':'mobile';const fit=form.querySelector<HTMLSelectElement>(`[name="${prefix}Fit"]`)!,position=form.querySelector<HTMLSelectElement>(`[name="${prefix}Position"]`)!,zoom=form.querySelector<HTMLInputElement>(`[name="${prefix}Zoom"]`)!;fit.value=state[name].fit;position.value=state[name].position;zoom.value=String(state[name].zoom);fit.onchange=()=>{state[name].fit=fit.value as BannerView['fit'];update(name)};position.onchange=()=>{state[name].position=position.value as BannerView['position'];update(name)};zoom.oninput=()=>{state[name].zoom=Number(zoom.value);update(name)};bindDrag(name);update(name)});form.onsubmit=async event=>{event.preventDefault();save.disabled=true;save.textContent='Saving…';try{const existing=bannerDesktop||bannerMobile||image(products[0]?.images[0]||'');const shared=await optimize(desktopInput.files?.[0]||existing);const result=await api<{desktop:string;mobile:string;desktopView:BannerView;mobileView:BannerView}>('/admin/banner',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({desktop:shared,desktopView:state.desktop,mobileView:state.mobile})});bannerDesktop=result.desktop;bannerMobile=result.mobile;bannerDesktopView=result.desktopView;bannerMobileView=result.mobileView;notify('Shop banner views updated');render()}catch(error){notify(`Banner save failed: ${(error as Error).message}`);save.disabled=false;save.textContent='Save banner views'}}}
function applyLocale(){document.querySelectorAll<HTMLButtonElement>('.locale-toggle [data-locale]').forEach(button=>button.classList.toggle('active',button.dataset.locale===locale));const nav=document.querySelectorAll<HTMLAnchorElement>('header nav a');if(nav[0])nav[0].lastChild!.textContent=tx('Shop','စျေးဝယ်ရန်');const orders=Array.from(nav).find(link=>link.href.endsWith('/orders'));if(orders)orders.textContent=tx('My Orders','ကျွန်ုပ်၏အော်ဒါများ');const profile=Array.from(nav).find(link=>link.href.endsWith('/profile')||link.href.endsWith('/login'));if(profile)profile.textContent=customerProfile?tx('Profile','ပရိုဖိုင်'):tx('Sign in','ဝင်ရန်');const dock=document.querySelectorAll<HTMLAnchorElement>('.mobile-dock a');if(dock[0])dock[0].querySelector(':scope > span:last-child')!.textContent=tx('Shop','စျေးဝယ်ရန်');if(dock[1])dock[1].querySelector(':scope > span:last-child')!.textContent=tx('My Orders','ကျွန်ုပ်၏အော်ဒါများ');if(dock[2])dock[2].querySelector(':scope > span:last-child')!.textContent=tx('Cart','စျေးဝယ်လှည်း');const shopTitle=document.querySelector('.customer:not(.route-page) .page-title h1');if(shopTitle)shopTitle.textContent=tx('Shop','စျေးဝယ်ရန်');const pageTitle=document.querySelector('.route-page .page-title h1');if(pageTitle)pageTitle.textContent=location.pathname==='/orders'?tx('My Orders','ကျွန်ုပ်၏အော်ဒါများ'):tx('Cart','စျေးဝယ်လှည်း');const icons=['<path d="M3 10.5 12 4l9 6.5v8H3z"></path><path d="M8 20v-5h8v5"></path>','<rect x="5" y="4" width="14" height="16" rx="2"></rect><path d="M8 9h8M8 13h8M8 17h4"></path>','<path d="M5 8h14l-1 12H6L5 8ZM8 8a4 4 0 0 1 8 0"></path>'];dock.forEach((link,index)=>{const svg=link.querySelector('svg');if(svg)svg.innerHTML=icons[index]});}
function bindUploadInputs(){document.querySelectorAll<HTMLInputElement>('[name="photos"]').forEach(input=>input.onchange=()=>{const label=input.closest('label');if(label)label.childNodes[0].textContent=input.files?.length?`${input.files.length} photo${input.files.length===1?'':'s'} selected `:'Add photos '})}
function applyCoverViews(){document.querySelectorAll<HTMLImageElement>('.product-image img').forEach((img,index)=>{const p=products[index];if(p){img.style.objectFit=p.coverFit||'cover';img.style.objectPosition=p.coverPosition||'center';img.style.transform='scale('+((p.coverZoom||100)/100)+')'}});const detailTone=decodeURIComponent(location.pathname.slice('/product/'.length));const detailProduct=products.find(p=>p.tone===detailTone);const detailImage=document.querySelector<HTMLImageElement>('#detail-image');if(detailProduct&&detailImage){detailImage.style.objectFit=detailProduct.coverFit||'cover';detailImage.style.objectPosition=detailProduct.coverPosition||'center'}}
function bindImageManagers() {
  document.querySelectorAll<HTMLFormElement>('[data-edit-product]').forEach(form => {
    const list = form.querySelector<HTMLElement>('.existing-photos');
    const upload = form.querySelector<HTMLLabelElement>('.file-input');
    if (!list || !upload) return;
    const tone = (form.querySelector('[name="tone"]') as HTMLInputElement).value;
    const productData = products.find(p => p.tone === tone);
    const manager = document.createElement('section');
    manager.className = 'image-manager';
    form.insertBefore(manager, upload);
    list.hidden = true;
    const photoLabels = () => Array.from(list.querySelectorAll<HTMLLabelElement>('label'));
    let selected = 0;
    let fit = productData?.coverFit || 'cover';
    let position = productData?.coverPosition || 'center';
    let zoom = productData?.coverZoom || 100;
    let dragged = -1;
    const draw = () => {
      const active = photoLabels().filter(label => (label.querySelector('input') as HTMLInputElement).checked);
      selected = Math.min(selected, Math.max(0, active.length - 1));
      const cover = active[selected]?.querySelector('img')?.src || '';
      manager.innerHTML = '<div class="photo-editor-layout"><div class="photo-editor-preview"><div class="photo-editor-card"><div class="photo-editor-frame"><img alt="Storefront card preview"></div><div class="photo-editor-caption"><b>' + esc(productData?.name || '') + '</b><small>Storefront card preview</small></div></div></div><div class="photo-editor-controls"><h3>Product photos</h3><p>Choose a cover photo, then adjust its appearance in the card.</p><div class="photo-editor-tiles"></div><div class="photo-editor-adjust"><label>Photo size <output>' + zoom + '%</output><input name="coverZoom" type="range" min="100" max="200" step="5" value="' + zoom + '"></label><label>Display<select name="coverFit"><option value="cover">Fill card</option><option value="contain">Show full photo</option></select></label><label>Position<select name="coverPosition"><option value="top">Top</option><option value="center">Center</option><option value="bottom">Bottom</option></select></label></div></div></div>';
      const frame = manager.querySelector<HTMLImageElement>('.photo-editor-frame img')!;
      frame.src = cover;
      const tileHost = manager.querySelector<HTMLElement>('.photo-editor-tiles')!;
      manager.querySelector('.photo-editor-controls')!.append(upload);
      active.forEach((label, index) => {
        const tile = document.createElement('div');
        tile.className = 'photo-editor-tile' + (index === selected ? ' selected' : '');
        tile.draggable = true;
        const choose = document.createElement('button');
        choose.type = 'button';
        choose.setAttribute('aria-label', 'Select photo ' + (index + 1) + ' as cover');
        choose.innerHTML = '<img alt="Product photo ' + (index + 1) + '">';
        choose.querySelector('img')!.src = label.querySelector('img')!.src;
        choose.onclick = () => { list.insertBefore(label, list.querySelector('label')); selected = 0; draw(); };
        const remove = document.createElement('button');
        remove.type = 'button';
        remove.className = 'photo-editor-remove';
        remove.textContent = '×';
        remove.title = 'Remove photo';
        remove.setAttribute('aria-label', 'Remove photo ' + (index + 1));
        remove.onclick = () => {
          if (active.length === 1) return notify('Keep at least one product photo');
          (label.querySelector('input') as HTMLInputElement).checked = false;
          selected = Math.max(0, Math.min(selected, active.length - 2));
          draw();
        };
        tile.ondragstart = () => { dragged = index; };
        tile.ondragover = event => event.preventDefault();
        tile.ondrop = event => {
          event.preventDefault();
          const source = active[dragged];
          const target = active[index];
          if (!source || !target || source === target) return;
          if (dragged < index) list.insertBefore(source, target.nextSibling);
          else list.insertBefore(source, target);
          selected = 0;
          draw();
        };
        tile.append(choose, remove);
        tileHost.append(tile);
      });
      const size = manager.querySelector<HTMLInputElement>('[name="coverZoom"]')!;
      const display = manager.querySelector<HTMLSelectElement>('[name="coverFit"]')!;
      const focal = manager.querySelector<HTMLSelectElement>('[name="coverPosition"]')!;
      display.value = fit;
      focal.value = position;
      const update = () => {
        zoom = Number(size.value);
        fit = display.value as 'cover' | 'contain';
        position = focal.value as 'top' | 'center' | 'bottom';
        frame.style.objectFit = fit;
        frame.style.objectPosition = position;
        frame.style.transform = 'scale(' + zoom / 100 + ')';
        manager.querySelector('output')!.textContent = zoom + '%';
      };
      size.oninput = update;
      display.onchange = update;
      focal.onchange = update;
      update();
    };
    manager.append(upload);
    const uploadInput = upload.querySelector<HTMLInputElement>('input')!;
    uploadInput.onchange = async () => {
      const files = Array.from(uploadInput.files || []);
      if (!files.length) return;
      upload.childNodes[0].textContent = 'Adding photos… ';
      try {
        for (const src of await readFiles(form)) {
          const label = document.createElement('label');
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.name = 'keepImage';
          checkbox.value = src;
          checkbox.checked = true;
          const img = document.createElement('img');
          img.src = src;
          label.append(checkbox, img);
          list.append(label);
        }
        uploadInput.value = '';
        upload.childNodes[0].textContent = 'Add photos ';
        selected = photoLabels().filter(label => (label.querySelector('input') as HTMLInputElement).checked).length - 1;
        draw();
      } catch { notify('Could not read the selected photos'); }
    };
    draw();
  });
}
function bindOrderTools(){const date=document.querySelector<HTMLInputElement>('#order-date');if(date)date.onchange=()=>{orderDate=date.value;render()};document.querySelector('#clear-order-date')?.addEventListener('click',()=>{orderDate='';render()});document.querySelector('#refresh-orders')?.addEventListener('click',async()=>{orders=await api<Order[]>('/admin/orders');render()})}
function bindSaveIndicators(){document.querySelectorAll<HTMLFormElement>('[data-edit-product]').forEach(form=>form.addEventListener('submit',event=>{const submitter=(event as SubmitEvent).submitter as HTMLButtonElement|null;if(submitter){submitter.disabled=true;submitter.textContent='Saving…'}}))}
function bindNewProductPanel(){const form=document.querySelector<HTMLFormElement>('#new-product');if(!form||form.dataset.panelBound)return;form.dataset.panelBound='true';form.hidden=true;const toggle=document.createElement('button');toggle.type='button';toggle.className='new-product-toggle';toggle.textContent='Add new product';toggle.setAttribute('aria-expanded','false');form.parentElement?.insertBefore(toggle,form);toggle.onclick=()=>{form.hidden=!form.hidden;toggle.textContent=form.hidden?'Add new product':'Close product form';toggle.setAttribute('aria-expanded',String(!form.hidden));if(!form.hidden)form.querySelector<HTMLInputElement>('input[name="name"]')?.focus()};form.addEventListener('submit',()=>{toggle.textContent='Adding product…';toggle.disabled=true})}
function bindStatusSelects(){document.querySelectorAll<HTMLSelectElement>('[data-status-select]').forEach(select=>select.onchange=async()=>{select.disabled=true;await status(select.dataset.statusSelect!,select.value)})}
function bindQuickAdd(){document.querySelectorAll<HTMLButtonElement>('[data-quick-add]').forEach(button=>button.onclick=e=>{e.preventDefault();const tone=button.dataset.quickAdd!,old=cart.find(item=>item.tone===tone&&item.variant===0);old?old.quantity++:cart.push({tone,variant:0,quantity:1});saveCart();render()})}
function bind(){document.querySelector('#login')?.addEventListener('submit',loginSubmit);document.querySelector('#logout')?.addEventListener('click',async()=>{await api('/admin/logout',{method:'POST'});isAdmin=false;render()});document.querySelectorAll<HTMLButtonElement>('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab!;render()});document.querySelectorAll<HTMLButtonElement>('[data-order-tab]').forEach(b=>b.onclick=()=>{orderTab=b.dataset.orderTab!;render()});document.querySelectorAll<HTMLButtonElement>('[data-add]').forEach(b=>b.onclick=()=>{const t=b.dataset.add!,v=Number((document.querySelector(`#v-${t.replace(/ /g,'-')}`)as HTMLSelectElement).value),old=cart.find(i=>i.tone===t&&i.variant===v);old?old.quantity++:cart.push({tone:t,variant:v,quantity:1});saveCart();render()});document.querySelector('#checkout')?.addEventListener('click',checkout);document.querySelectorAll<HTMLButtonElement>('[data-status]').forEach(b=>b.onclick=()=>status(b.dataset.status!,b.dataset.next!));document.querySelectorAll<HTMLFormElement>('[data-price]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const d=new FormData(f);await api(`/admin/products/${encodeURIComponent(String(d.get('tone')))}/variants/${d.get('variant')}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({price:Number(d.get('price'))})});products=await api<Product[]>('/products');render()});document.querySelector('#new-product')?.addEventListener('submit',createProduct);document.querySelectorAll<HTMLFormElement>('[data-edit-product]').forEach(f=>f.addEventListener('submit',editProduct));document.querySelectorAll<HTMLButtonElement>('[data-delete]').forEach(b=>b.onclick=()=>deleteProduct(b.dataset.delete!));document.querySelector('#change-pass')?.addEventListener('submit',changePass);document.querySelector('#find-order')?.addEventListener('click',findOrder);}
function shop(){if(location.pathname==='/forgot-password'||location.pathname==='/reset-password')return authPage(location.pathname);return `<main class="customer"><div class="page-title"><h1>${tx('Shop','စျေးဝယ်ရန်')}</h1><span>${products.length} ${tx('products','ကုန်ပစ္စည်းများ')}</span></div><section id="catalog" class="grid">${products.map(p=>`<a class="card product-link" href="/product/${encodeURIComponent(p.tone)}"><div class="product-image"><img src="${image(p.images[0])}" alt="${esc(p.name)}"><span>${esc(p.name)}</span></div><div class="card-copy"><h2>${esc(p.name)}</h2><b>${tx('From','စျေးနှုန်းမှ')} ${esc(p.prices[0].price)}</b><span class="view-product">${tx('View product','အသေးစိတ်ကြည့်ရန်')}</span></div></a>`).join('')}</section></main>`}
function cartPage(){
  const complete=!!customerProfile?.name&&!!customerProfile.phone&&!!customerProfile.city&&!!customerProfile.deliveryAddress;
  const delivery=customerProfile?`<div class="delivery-summary"><b>${complete?`Deliver to ${esc(customerProfile.name)}`:'Delivery details needed'}</b>${complete?`<p>${esc(customerProfile.phone)} · ${esc(customerProfile.city)}</p><p>${esc(customerProfile.deliveryAddress)}</p>`:'<p>Add your name, phone, city or town, and delivery address before ordering.</p>'}<a href="/profile">${complete?'Edit delivery details':'Complete profile'}</a></div>`:'<div class="delivery-summary"><p>Sign in to save your delivery details and place an order.</p><a class="account-link" href="/login?next=%2Fcart">Sign in</a> <a href="/signup?next=%2Fcart">Create account</a></div>';
  const itemCount=cart.reduce((n,i)=>n+i.quantity,0);
  return `<main class="customer route-page"><div class="page-title"><h1>Cart</h1><span>${cart.length?`${itemCount} items · ပစ္စည်း ${itemCount} ခု`:'Your cart is empty'}</span></div><section class="bag cart-panel">${cart.map(i=>`<div class="cart-card"><img src="${image(product(i.tone).images[0])}" alt=""><div><h2>${esc(product(i.tone).name)}</h2><p>${esc(product(i.tone).prices[i.variant].label)} × ${i.quantity}</p></div><b>${money(amount(product(i.tone).prices[i.variant].price)*i.quantity)}</b></div>`).join('')||'<p>Your cart is empty.</p>'}<b class="bag-total">Total ${money(total())}</b>${delivery}<button id="checkout" ${cart.length&&complete?'':'disabled'}>Place order</button></section></main>`;
}
function ordersPage(){return `<main class="customer route-page"><div class="page-title"><h1>My Orders</h1><span>Order history</span></div><section id="orders" class="bag"><div id="order-list"><p>Loading orders…</p></div></section></main>`}
function detailPage(){const tone=decodeURIComponent(location.pathname.slice('/product/'.length)),p=product(tone);if(!p)return '<main class="empty">Product not found</main>';return `<main class="product-detail"><div class="breadcrumbs"><a href="/">${tx('Home','ပင်မစာမျက်နှာ')}</a> / ${tx('Shop','စျေးဝယ်ရန်')} / ${esc(p.name)}</div><div class="detail-layout"><section><div class="detail-main-image"><img id="detail-image" src="${image(p.images[0])}" alt="${esc(p.name)}"></div><div class="thumbnail-row">${p.images.map((src,i)=>`<button data-thumb="${i}" data-src="${image(src)}"><img src="${image(src)}" alt=""></button>`).join('')}</div></section><section class="detail-info"><small>YOURS CAYCI / STOCKINGS</small><h1>${esc(p.name)}</h1><h2>${esc(p.prices[0].price)}</h2><label>${tx('Choose fit','အရွယ်အစားရွေးပါ')}</label><div class="variant-buttons">${p.prices.map((v,i)=>`<button data-variant="${i}" class="${i===0?'selected':''}">${esc(v.label)}<small>${esc(v.fit)} · ${esc(v.price)}</small></button>`).join('')}</div><div class="detail-actions"><div class="quantity"><button data-qty="-1">−</button><span id="quantity">1</span><button data-qty="1">+</button></div><button id="detail-add">${tx('Add to cart','လှည်းထဲထည့်ရန်')}</button></div></section></div></main>`}
function bindDetail(){if(!location.pathname.startsWith('/product/'))return;const p=product(decodeURIComponent(location.pathname.slice('/product/'.length)));if(!p)return;let selected=0,quantity=1;document.querySelectorAll<HTMLButtonElement>('[data-thumb]').forEach(button=>button.onclick=()=>{(document.querySelector('#detail-image')as HTMLImageElement).src=button.dataset.src!});document.querySelectorAll<HTMLButtonElement>('[data-variant]').forEach(button=>button.onclick=()=>{selected=Number(button.dataset.variant);document.querySelectorAll('[data-variant]').forEach(item=>item.classList.remove('selected'));button.classList.add('selected');(document.querySelector('.detail-info h2')as HTMLElement).textContent=p.prices[selected].price});document.querySelectorAll<HTMLButtonElement>('[data-qty]').forEach(button=>button.onclick=()=>{quantity=Math.max(1,quantity+Number(button.dataset.qty));document.querySelector('#quantity')!.textContent=String(quantity)});document.querySelector('#detail-add')?.addEventListener('click',()=>{const old=cart.find(item=>item.tone===p.tone&&item.variant===selected);old?old.quantity+=quantity:cart.push({tone:p.tone,variant:selected,quantity});saveCart();notify(`${p.name} added to cart`);render()})}
function login(){return `<main class="login"><a class="logo" href="/">Yours CayCi</a><h1>Admin sign in</h1><form id="login"><label>Passcode</label><input id="passcode" type="password" required><button>Sign in</button><small id="login-error"></small></form></main>`}
const citySuggestions='<datalist id="myanmar-cities"><option value="Yangon"><option value="Mandalay"><option value="Naypyidaw"><option value="Bago"><option value="Mawlamyine"><option value="Taunggyi"><option value="Pathein"><option value="Pyin Oo Lwin"><option value="Monywa"><option value="Meiktila"><option value="Myitkyina"><option value="Sittwe"><option value="Hpa-An"></datalist>';
type SignupDraft={method:'email'|'phone';identifier:string;password:string};
let signupDraft:SignupDraft|null=null;
function deliveryFields(profile?:CustomerProfile,phone?:string,locked=false){return `<label>Full name<input name="name" autocomplete="name" value="${esc(profile?.name||'')}" required maxlength="120"></label><label>Phone number<input name="phone" type="tel" autocomplete="tel" inputmode="tel" placeholder="09…" value="${esc(phone??profile?.phone??'')}" ${locked?'readonly':''} required></label><label>City / town in Myanmar<input name="city" list="myanmar-cities" autocomplete="address-level2" value="${esc(profile?.city||'')}" required maxlength="120"></label><label>Delivery address<textarea name="deliveryAddress" autocomplete="street-address" required maxlength="500" rows="3">${esc(profile?.deliveryAddress||'')}</textarea></label>${citySuggestions}`}
function authPage(route:string){
  const next=location.search;
  if(customerProfile&&route!=='/forgot-password'&&route!=='/reset-password')return `<main class="customer account-page"><h1>You are signed in</h1><a href="/profile">View profile</a></main>`;
  if(route==='/login')return `<main class="customer account-page"><section class="account-card"><h1>Sign in</h1>${new URLSearchParams(location.search).get('error')==='social'?'<p class="form-error" role="alert">Social sign-in could not be completed. Please try again.</p>':''}<form id="customer-login"><label>Email or Myanmar phone<input name="identifier" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button type="submit">Sign in</button><p class="form-error" role="alert"></p></form><p><a href="/forgot-password">Forgot password?</a></p><p>New to Yours CayCi? <a href="/signup${next}">Create account</a></p>${socialButtons()}</section></main>`;
  if(route==='/forgot-password')return `<main class="customer account-page"><section class="account-card"><h1>Reset password</h1><p>Enter the email linked to your account. We’ll send a reset link.</p><form id="forgot-password"><label>Email<input name="email" type="email" autocomplete="email" required></label><button type="submit">Send reset link</button><p class="form-error" role="status"></p></form><p>Signed up with only a phone number? Contact the store for help.</p><p><a href="/login">Back to sign in</a></p></section></main>`;
  if(route==='/reset-password')return `<main class="customer account-page"><section class="account-card"><h1>Choose a new password</h1><form id="reset-password"><label>New password<input name="password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label><button type="submit">Update password</button><p class="form-error" role="status"></p></form><p><a href="/login">Back to sign in</a></p></section></main>`;
  if(route==='/signup/delivery'){
    if(!signupDraft)return `<main class="customer account-page"><section class="account-card"><h1>Delivery details</h1><p>Start with your account details.</p><a href="/signup${next}">Start registration</a></section></main>`;
    return `<main class="customer account-page"><section class="account-card"><small>Step 2 of 2 · Delivery</small><h1>Where should we deliver?</h1><form id="signup-delivery">${deliveryFields(undefined,signupDraft.method==='phone'?signupDraft.identifier:undefined,signupDraft.method==='phone')}${signupDraft.method==='phone'?'<small>Your login phone number is used for delivery. You can change it later in Profile.</small>':''}<div class="account-actions"><button type="button" id="signup-back" class="secondary-button">Back</button><button type="submit">Create account</button></div><p class="form-error" role="alert"></p></form></section></main>`;
  }
  return `<main class="customer account-page"><section class="account-card"><small>Step 1 of 2 · Account</small><h1>Create account</h1><div class="account-methods"><button type="button" data-method="email" class="${signupDraft?.method!=='phone'?'active':''}">Email</button><button type="button" data-method="phone" class="${signupDraft?.method==='phone'?'active':''}">Phone</button></div><form id="signup-account"><label id="signup-identifier-label">${signupDraft?.method==='phone'?'Myanmar phone':'Email'}<input name="identifier" type="${signupDraft?.method==='phone'?'tel':'email'}" autocomplete="username" value="${esc(signupDraft?.identifier||'')}" placeholder="${signupDraft?.method==='phone'?'09…':'you@example.com'}" required></label><label>Password<input name="password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label><button type="submit">Continue to delivery</button><p class="form-error" role="alert"></p></form><p>Already have an account? <a href="/login${next}">Sign in</a></p>${socialButtons()}</section></main>`;
}
const telegramInitData = new URLSearchParams(location.hash.slice(1)).get('tgWebAppData') || '';
if(telegramInitData)sessionStorage.setItem('yc_telegram_init',telegramInitData);
const miniAppData=()=>telegramInitData||sessionStorage.getItem('yc_telegram_init')||'';
function socialButtons(){return `<div class="social-signin"><span>Or continue with</span>${miniAppData()?'<button type="button" data-telegram-login>Sign in with Telegram</button>':'<a href="https://t.me/yourscayciorderbot?startapp">Open in Telegram</a>'}</div>`}
document.addEventListener('click',async event=>{
  const button=(event.target as HTMLElement).closest<HTMLButtonElement>('[data-telegram-login]');
  if(!button)return;
  button.disabled=true;button.textContent='Signing in…';
  try{const result=await api<{profile:CustomerProfile}>('/customer/telegram-miniapp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({initData:miniAppData()})});sessionStorage.removeItem('yc_telegram_init');customerProfile=result.profile;location.href=customerProfile.phone&&customerProfile.city&&customerProfile.deliveryAddress?'/orders':'/profile?complete=1'}catch(error){notify((error as Error).message);button.disabled=false;button.textContent='Sign in with Telegram'}
});
