function formValues(form:HTMLFormElement){const values:Record<string,string>={};new FormData(form).forEach((value,key)=>{values[key]=String(value)});return values}
function afterCustomerLogin(profile:CustomerProfile){customerProfile=profile;signupDraft=null;const next=new URLSearchParams(location.search).get('next');location.href=next?.startsWith('/')&&!next.startsWith('//')?next:'/profile'}
function bindCustomerForms(){
  const forgot=document.querySelector<HTMLFormElement>('#forgot-password');if(forgot)forgot.onsubmit=async event=>{event.preventDefault();const button=forgot.querySelector<HTMLButtonElement>('button')!,result=forgot.querySelector<HTMLElement>('.form-error')!;button.disabled=true;result.textContent='';try{const response=await api<{message:string}>('/customer/password-reset/request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:String(new FormData(forgot).get('email'))})});result.textContent=response.message}catch(error){result.textContent=(error as Error).message}finally{button.disabled=false}};
  const reset=document.querySelector<HTMLFormElement>('#reset-password');if(reset)reset.onsubmit=async event=>{event.preventDefault();const button=reset.querySelector<HTMLButtonElement>('button')!,result=reset.querySelector<HTMLElement>('.form-error')!;button.disabled=true;result.textContent='';try{await api('/customer/password-reset/confirm',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:new URLSearchParams(location.search).get('token'),password:String(new FormData(reset).get('password'))})});result.textContent='Password updated. You can sign in now.';reset.reset()}catch(error){result.textContent=(error as Error).message;button.disabled=false}};
  const methods=document.querySelectorAll<HTMLButtonElement>('[data-method]');
  methods.forEach(button=>button.onclick=()=>{const method=button.dataset.method as 'email'|'phone';methods.forEach(item=>item.classList.toggle('active',item===button));const label=document.querySelector<HTMLElement>('#signup-identifier-label')!;label.firstChild!.textContent=method==='phone'?'Myanmar phone':'Email';const input=label.querySelector<HTMLInputElement>('input')!;input.type=method==='phone'?'tel':'email';input.placeholder=method==='phone'?'09…':'you@example.com';input.value='';(document.querySelector('#signup-account') as HTMLFormElement).dataset.method=method});
  const account=document.querySelector<HTMLFormElement>('#signup-account');
  if(account)account.onsubmit=event=>{event.preventDefault();const values=formValues(account);signupDraft={method:account.dataset.method==='phone'||(!account.dataset.method&&signupDraft?.method==='phone')?'phone':'email',identifier:values.identifier.trim(),password:values.password};if(signupDraft.method==='phone'&&!/^(?:09\d{7,9}|\+?959\d{7,9})$/.test(signupDraft.identifier.replace(/[ -]/g,''))){account.querySelector<HTMLElement>('.form-error')!.textContent='Enter a valid Myanmar phone number';return}history.pushState({},'',`/signup/delivery${location.search}`);render()};
  document.querySelector('#signup-back')?.addEventListener('click',()=>{history.pushState({},'',`/signup${location.search}`);render()});
  const delivery=document.querySelector<HTMLFormElement>('#signup-delivery');
  if(delivery)delivery.onsubmit=async event=>{event.preventDefault();if(!signupDraft)return;const button=delivery.querySelector<HTMLButtonElement>('button[type="submit"]')!,error=delivery.querySelector<HTMLElement>('.form-error')!;button.disabled=true;button.textContent='Creating account…';error.textContent='';try{const values=formValues(delivery);const payload={...values,email:signupDraft.method==='email'?signupDraft.identifier:null,password:signupDraft.password};const result=await api<{profile:CustomerProfile}>('/customer/signup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});afterCustomerLogin(result.profile)}catch(e){error.textContent=(e as Error).message;button.disabled=false;button.textContent='Create account'}};
  const login=document.querySelector<HTMLFormElement>('#customer-login');
  if(login)login.onsubmit=async event=>{event.preventDefault();const button=login.querySelector<HTMLButtonElement>('button[type="submit"]')!,error=login.querySelector<HTMLElement>('.form-error')!;button.disabled=true;button.textContent='Signing in…';error.textContent='';try{const result=await api<{profile:CustomerProfile}>('/customer/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(formValues(login))});afterCustomerLogin(result.profile)}catch(e){error.textContent=(e as Error).message;button.disabled=false;button.textContent='Sign in'}};
  const profile=document.querySelector<HTMLFormElement>('#customer-profile');
  if(profile)profile.onsubmit=async event=>{event.preventDefault();const button=profile.querySelector<HTMLButtonElement>('button[type="submit"]')!,error=profile.querySelector<HTMLElement>('.form-error')!;button.disabled=true;button.textContent='Saving…';error.textContent='';try{const result=await api<{profile:CustomerProfile}>('/customer/profile',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(formValues(profile))});customerProfile=result.profile;button.textContent='Saved';notify('Delivery details saved');setTimeout(()=>{button.disabled=false;button.textContent='Save changes'},1500)}catch(e){error.textContent=(e as Error).message;button.disabled=false;button.textContent='Save changes'}};
  document.querySelector('#customer-logout')?.addEventListener('click',async()=>{await api('/customer/logout',{method:'POST'});customerProfile=null;location.href='/login'});
}
window.addEventListener('popstate',()=>{if(!adminRoute()&&!developerRoute())render()});
function developerLogin(){return `<main class="developer-login"><section class="developer-card"><small>PRIVATE DEVELOPER ACCESS</small><h1>System observability</h1><p>Review application health, usage, capacity, and recent events.</p><form id="developer-login"><input id="developer-passcode" type="password" placeholder="Developer passcode" autocomplete="current-password" required><button>Open dashboard</button><p id="developer-login-error" class="form-error"></p></form></section></main>`}
function developer(){return `<main class="developer-page"><div class="developer-heading"><div><small>PRIVATE DEVELOPER ACCESS</small><h1>System observability</h1><p>Usage and capacity signals from the application database.</p></div><div><button id="developer-refresh">Refresh</button><button id="developer-logout" class="secondary-button">Sign out</button></div></div><section class="developer-section developer-operations"><div><h2>Maintenance</h2><p>Pause the storefront and customer API. Developer and store admin access remain available.</p><strong id="maintenance-state">Checking status…</strong><button id="maintenance-toggle" type="button" disabled>Loading…</button></div><div><h2>Capacity</h2><div id="developer-capacity">Loading capacity…</div><details class="capacity-settings"><summary>Set alert thresholds</summary><form id="capacity-limits"><label>Database storage threshold (MB)<input name="storageMb" type="number" min="1" max="1000000" placeholder="From Neon plan"></label><label>Requests per minute threshold<input name="requestsPerMinute" type="number" min="1" max="1000000" placeholder="From load test"></label><button type="submit">Save thresholds</button><p class="form-error" role="alert"></p></form><small>These are alert thresholds. They do not change provider quotas or load balance traffic.</small></details></div></section><section id="developer-metrics" class="developer-grid"><p>Loading metrics…</p></section><section class="developer-section developer-flow"><div class="developer-section-heading"><h2>Request data</h2><span>Developer controls</span></div><p>Turn off routine request logs to reduce database writes. Errors and staff actions stay recorded.</p><div class="developer-flow-controls"><label>Request logging<select id="request-logging-mode"><option value="full">Full request logs</option><option value="errors-only">Errors and staff actions only</option></select></label><label>Delete routine logs older than<select id="request-log-days"><option value="7">7 days</option><option value="30" selected>30 days</option><option value="90">90 days</option><option value="365">365 days</option></select></label></div><div id="request-log-preview" role="status">Checking old request logs…</div><small>Cleanup deletes at most 1,000 routine request events per batch. Orders, customers, errors, and audit events are kept.</small></section><section class="developer-section"><div class="developer-section-heading"><h2>Customers</h2><span>25 per page</span></div><div id="developer-users">Loading customers…</div><div class="developer-pagination"><button id="users-prev" type="button">Previous</button><span id="users-page"></span><button id="users-next" type="button">Next</button></div></section><section class="developer-section"><div class="developer-section-heading"><h2>Recent events</h2><span>Latest 100 recorded events</span></div><div id="developer-logs"><p>Loading events…</p></div></section></main>`}
function maintenanceScreen(){document.querySelector('#app')!.innerHTML=`<main class="maintenance-screen"><div class="maintenance-card"><small>YOURS CAYCI</small><h1>${tx('We’ll be back soon','မကြာမီ ပြန်လည်ဖွင့်လှစ်ပါမည်')}</h1><p>${tx('The shop is temporarily under maintenance. Please try again shortly.','ဆိုင်ကို ခေတ္တ ပြုပြင်ထိန်းသိမ်းနေပါသည်။ ခဏအကြာတွင် ပြန်လည်ကြိုးစားပါ။')}</p><button type="button" id="maintenance-retry">${tx('Try again','ပြန်လည်ကြိုးစားရန်')}</button></div><div class="locale-toggle maintenance-locale" aria-label="Language"><button type="button" data-locale="en" class="${locale==='en'?'active':''}">EN</button><button type="button" data-locale="mm" class="${locale==='mm'?'active':''}">MM</button></div></main>`;document.querySelector('#maintenance-retry')?.addEventListener('click',()=>location.reload());document.querySelectorAll<HTMLButtonElement>('.maintenance-locale [data-locale]').forEach(button=>button.onclick=()=>{locale=button.dataset.locale==='mm'?'mm':'en';localStorage.setItem('yc_locale',locale);maintenanceScreen()})}
async function refreshDeveloper(){await Promise.all([loadDeveloperData(),loadDeveloperOperations(),loadDeveloperUsers(),loadRequestLogPreview()])}
async function loadRequestLogPreview(){const days=Number((document.querySelector('#request-log-days') as HTMLSelectElement)?.value||30),target=document.querySelector<HTMLElement>('#request-log-preview');if(!target)return;const data=await api<{eligibleCount:number;estimatedBytes:string;batchSize:number}>(`/developer/request-logs?days=${days}`);target.dataset.count=String(data.eligibleCount);target.innerHTML=`<p><b>${data.eligibleCount.toLocaleString()}</b> routine request logs older than ${days} days · about ${(Number(data.estimatedBytes)/1048576).toFixed(1)} MB of row data</p><button type="button" id="delete-old-request-logs" ${data.eligibleCount?'':'disabled'}>Delete next ${Math.min(data.eligibleCount,data.batchSize).toLocaleString()}</button><small>Postgres may reuse freed space before the database size falls.</small>`}
function openDeveloperCleanup(){const days=Number((document.querySelector('#request-log-days') as HTMLSelectElement).value),count=Number(document.querySelector<HTMLElement>('#request-log-preview')?.dataset.count||0);if(!count)return;const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<section class="confirm-modal"><h2>Delete old request logs?</h2><p>Delete up to ${Math.min(count,1000).toLocaleString()} routine request events older than ${days} days. Orders, customer accounts, errors, and audit events stay in place.</p><div><button type="button" class="modal-secondary" data-close>Keep logs</button><button type="button" class="modal-primary" data-confirm>Delete this batch</button></div><p class="form-error" role="alert"></p></section>`;document.body.append(modal);modal.querySelector('[data-close]')?.addEventListener('click',()=>modal.remove());modal.querySelector<HTMLButtonElement>('[data-confirm]')?.addEventListener('click',async event=>{const button=event.currentTarget as HTMLButtonElement;button.disabled=true;try{const result=await api<{deleted:number}>('/developer/request-logs',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({days,confirm:'DELETE REQUEST LOGS'})});modal.remove();notify(`${result.deleted} old request logs deleted`);await Promise.all([loadRequestLogPreview(),loadDeveloperOperations(),loadDeveloperData()])}catch(error){modal.querySelector<HTMLElement>('.form-error')!.textContent=(error as Error).message;button.disabled=false}})}
function bindDeveloperOperations(){document.querySelector('#maintenance-toggle')?.addEventListener('click',async()=>{const button=document.querySelector<HTMLButtonElement>('#maintenance-toggle')!,enabled=button.dataset.enabled==='true';if(!window.confirm(enabled?'Resume the storefront now?':'Pause the storefront and customer ordering now?'))return;button.disabled=true;try{await api('/developer/maintenance',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:!enabled})});await loadDeveloperOperations();notify(enabled?'Storefront resumed':'Storefront paused')}catch(error){notify((error as Error).message);button.disabled=false}});document.querySelector('#users-prev')?.addEventListener('click',()=>{developerUserPage=Math.max(1,developerUserPage-1);loadDeveloperUsers().catch(error=>notify((error as Error).message))});document.querySelector('#users-next')?.addEventListener('click',()=>{developerUserPage++;loadDeveloperUsers().catch(error=>notify((error as Error).message))});document.querySelector<HTMLSelectElement>('#request-log-days')?.addEventListener('change',()=>loadRequestLogPreview().catch(error=>notify((error as Error).message)));document.querySelector<HTMLSelectElement>('#request-logging-mode')?.addEventListener('change',async event=>{const select=event.currentTarget as HTMLSelectElement;select.disabled=true;try{await api('/developer/request-logging',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:select.value})});notify(select.value==='full'?'Full request logging enabled':'Routine request logging paused');await Promise.all([loadDeveloperOperations(),loadDeveloperData()])}catch(error){notify((error as Error).message);await loadDeveloperOperations()}finally{select.disabled=false}});document.querySelector('#request-log-preview')?.addEventListener('click',event=>{if((event.target as HTMLElement).closest('#delete-old-request-logs'))openDeveloperCleanup()});document.querySelector<HTMLFormElement>('#capacity-limits')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget as HTMLFormElement,button=form.querySelector<HTMLButtonElement>('button')!,error=form.querySelector<HTMLElement>('.form-error')!,data=new FormData(form),storage=String(data.get('storageMb')||'').trim(),requests=String(data.get('requestsPerMinute')||'').trim();button.disabled=true;error.textContent='';try{await api('/developer/capacity',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({storageMb:storage?Number(storage):null,requestsPerMinute:requests?Number(requests):null})});await loadDeveloperOperations();notify('Capacity thresholds saved')}catch(cause){error.textContent=(cause as Error).message}finally{button.disabled=false}});}
let developerUserPage=1;
function capacityMeter(label:string,current:number|null,limit:number|null,unit:string){const ratio=current!==null&&limit?current/limit:null,status=current===null?'Not measured':limit===null?'Set threshold':ratio!==null&&ratio>=.9?'Danger':ratio!==null&&ratio>=.7?'Watch':'Good',level=ratio===null?'unknown':ratio>=.9?'danger':ratio>=.7?'watch':'good',format=(value:number)=>unit==='MB'?value.toFixed(1):value.toLocaleString();return `<div class="capacity-meter ${level}"><div><span>${esc(label)}</span><b>${current===null?'—':format(current)} / ${limit===null?'—':format(limit)} ${unit}</b><strong>${status}</strong></div><div class="capacity-track" role="progressbar" aria-label="${esc(label)}" aria-valuemin="0" ${current===null||limit===null?'':`aria-valuenow="${Math.round(current)}" aria-valuemax="${Math.round(limit)}"`}><i style="width:${ratio===null?0:Math.max(2,Math.min(100,ratio*100))}%"></i></div></div>`}
async function loadDeveloperOperations(){
  const [maintenance,capacity]=await Promise.all([api<{enabled:boolean}>('/developer/maintenance'),api<{connections:{active:number;max:number};throughput:{requests_hour:number;requests_minute:number;errors_hour:number};databaseBytes:string;tables:{name:string;bytes:string}[];limits:{storageMb:number|null;requestsPerMinute:number|null};loggingMode:'full'|'errors-only';note:string}>('/developer/capacity')]);
  const state=document.querySelector('#maintenance-state'),button=document.querySelector<HTMLButtonElement>('#maintenance-toggle'),target=document.querySelector('#developer-capacity'),mode=document.querySelector<HTMLSelectElement>('#request-logging-mode');
  if(state)state.textContent=maintenance.enabled?'Storefront paused':'Storefront live';
  if(button){button.disabled=false;button.textContent=maintenance.enabled?'Resume storefront':'Pause storefront';button.dataset.enabled=String(maintenance.enabled)}
  if(mode)mode.value=capacity.loggingMode;
  const form=document.querySelector<HTMLFormElement>('#capacity-limits');if(form){(form.elements.namedItem('storageMb') as HTMLInputElement).value=capacity.limits.storageMb?.toString()||'';(form.elements.namedItem('requestsPerMinute') as HTMLInputElement).value=capacity.limits.requestsPerMinute?.toString()||''}
  if(target)target.innerHTML=`${capacityMeter('Postgres connections',capacity.connections.active,capacity.connections.max,'connections')}${capacityMeter('Database storage',Number(capacity.databaseBytes)/1048576,capacity.limits.storageMb,'MB')}${capacityMeter('Recorded requests per minute',capacity.loggingMode==='full'?capacity.throughput.requests_minute:null,capacity.limits.requestsPerMinute,'requests')}<p><b>${capacity.throughput.errors_hour}</b> server errors last hour</p>${capacity.loggingMode==='errors-only'?'<p class="muted">Routine request logging is off, so request counts and active users are not measured.</p>':''}<details><summary>Largest database tables</summary>${capacity.tables.map(t=>`<p>${esc(t.name)} · ${(Number(t.bytes)/1048576).toFixed(1)} MB</p>`).join('')}</details><small>${esc(capacity.note)}</small>`
}
async function loadDeveloperUsers(){const result=await api<{users:{id:string;email:string|null;name:string;phone:string;city:string;deliveryAddress:string;createdAt:string}[];page:number;total:number;pageSize:number}>(`/developer/users?page=${developerUserPage}`);const target=document.querySelector('#developer-users');if(target)target.innerHTML=`<div class="developer-user-list">${result.users.map(u=>`<article><div><b>${esc(u.name||'Unnamed')}</b><small>Account ${esc(u.id)} · joined ${dateText(u.createdAt)}</small></div><div>${esc(u.email||'No email')}<br>${esc(u.phone||'No phone')}</div><div>${esc(u.city||'No city')}<br>${esc(u.deliveryAddress||'No address')}</div></article>`).join('')||'<p>No customers yet.</p>'}</div>`;const page=document.querySelector('#users-page');if(page)page.textContent=`Page ${result.page} of ${Math.max(1,Math.ceil(result.total/result.pageSize))} · ${result.total} customers`;const prev=document.querySelector<HTMLButtonElement>('#users-prev'),next=document.querySelector<HTMLButtonElement>('#users-next');if(prev)prev.disabled=result.page<=1;if(next)next.disabled=result.page*result.pageSize>=result.total}
async function loadDeveloperData(){const metrics=await api<{users:{total:number;today:number;month:number};activeUsers15m:number;storage:{database_bytes:string;product_image_bytes:string;settings_bytes:string};busyHours:{hour:number;requests:number}[];errors:{total:number;today:number};orders:{total:number;today:number};loggingMode:'full'|'errors-only';generatedAt:string}>('/developer/metrics');const logs=await api<{id:number;eventType:string;method:string;path:string;status:number;message:string|null;createdAt:string}[]>('/developer/logs');const formatBytes=(value:string)=>{let n=Number(value)||0;const units=['B','KB','MB','GB'];let i=0;while(n>=1024&&i<units.length-1){n/=1024;i++}return `${n.toFixed(i?1:0)} ${units[i]}`};const metricsTarget=document.querySelector('#developer-metrics');if(metricsTarget)metricsTarget.innerHTML=`<article><small>Users today</small><b>${metrics.users.today}</b><span>${metrics.users.total} total · ${metrics.users.month} this month</span></article><article><small>Active users</small><b>${metrics.loggingMode==='full'?metrics.activeUsers15m:'—'}</b><span>${metrics.loggingMode==='full'?'unique users in the last 15 minutes':'Routine request logging is off'}</span></article><article><small>Orders today</small><b>${metrics.orders.today}</b><span>${metrics.orders.total} total orders</span></article><article><small>Errors</small><b>${metrics.errors.today}</b><span>${metrics.errors.total} recorded errors</span></article><article><small>Database size</small><b>${formatBytes(metrics.storage.database_bytes)}</b><span>Postgres database</span></article><article><small>Image data estimate</small><b>${formatBytes(metrics.storage.product_image_bytes)}</b><span>product image payloads</span></article><article class="developer-wide"><small>Recorded busy hours · last 30 days</small><div class="busy-hours">${metrics.busyHours.map(item=>`<span><b>${String(item.hour).padStart(2,'0')}:00</b><i style="height:${Math.max(8,Math.min(100,item.requests))}%"></i><em>${item.requests}</em></span>`).join('')||'<span>No request data yet.</span>'}</div></article><p class="developer-updated">Updated ${dateText(metrics.generatedAt)}</p>`;const logTarget=document.querySelector('#developer-logs');if(logTarget)logTarget.innerHTML=logs.map(log=>`<div class="developer-log ${log.eventType==='error'?'error':''}"><time>${dateText(log.createdAt)}</time><b>${esc(log.eventType)}</b><span>${esc(log.method||'')} ${esc(log.path||'')}</span><small>${log.status||''} ${esc(log.message||'')}</small></div>`).join('')||'<p>No events recorded yet.</p>'}
function bindDeveloper(){const login=document.querySelector<HTMLFormElement>('#developer-login');if(login)login.onsubmit=async event=>{event.preventDefault();const error=document.querySelector<HTMLElement>('#developer-login-error')!,button=login.querySelector<HTMLButtonElement>('button')!;button.disabled=true;error.textContent='';try{await api('/developer/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({passcode:(document.querySelector('#developer-passcode') as HTMLInputElement).value})});isDeveloper=true;render()}catch(e){error.textContent=(e as Error).message;button.disabled=false}};document.querySelector('#developer-refresh')?.addEventListener('click',()=>refreshDeveloper().catch(e=>notify((e as Error).message)));document.querySelector('#developer-logout')?.addEventListener('click',async()=>{await api('/developer/logout',{method:'POST'});isDeveloper=false;render()});if(isDeveloper&&document.querySelector('#developer-metrics')){bindDeveloperOperations();refreshDeveloper().catch(e=>notify((e as Error).message))}}
function admin(){return `<div class="admin-layout"><aside><a class="logo" href="/admin">Yours CayCi</a><b>Admin</b><button data-tab="orders">Orders</button><button data-tab="products">Products</button><button data-tab="reports">Reports</button><button data-tab="settings">Settings</button><a href="/">Storefront</a><button id="logout">Sign out</button></aside><main class="admin-main">${tab==='orders'?ordersView():tab==='products'?productsView():tab==='reports'?reportsView():settingsView()}</main></div>`}
function ordersView(){const states=['Pending','Confirmed','Shipped','Delivered'];const visible=orders.filter(o=>(orderTab==='cancelled'?o.status==='Cancelled':o.status!=='Cancelled')&&(!orderDate||dateKey(o.createdAt)===orderDate)).sort((a,b)=>new Date(b.createdAt||0).getTime()-new Date(a.createdAt||0).getTime());return `<div class="admin-heading"><h1>Orders</h1><span>${visible.length} shown</span></div><section class="admin-section order-panel"><div class="order-toolbar"><div class="order-tabs"><button data-order-tab="active" class="${orderTab==='active'?'selected':''}">Active orders</button><button data-order-tab="cancelled" class="${orderTab==='cancelled'?'selected':''}">Cancelled orders</button></div><div class="date-tools"><label>Order date <input id="order-date" type="date" value="${orderDate}"></label>${orderDate?'<button id="clear-order-date">All dates</button>':''}<button id="refresh-orders">Refresh</button></div></div><p class="muted">Newest orders are shown first. Select a date to review earlier orders.</p><table><thead><tr><th>Order & date</th><th>Customer</th><th>Items</th><th>Total</th><th>Status</th></tr></thead><tbody>${visible.map(o=>{const allowed=o.status==='Pending'?states:states.slice(1);return `<tr><td><b>${orderCode(o.id)}</b><small class="order-date">${dateText(o.createdAt)}</small></td><td>${esc(o.customer)}<br>${esc(o.phone||'')}<br>${esc(o.address||'')}<br>${o.cancelRequested?'Cancel requested':''}</td><td>${o.items.map(i=>`${esc(i.tone)} × ${i.quantity}`).join(', ')}</td><td><b>${money(Number(o.total))}</b></td><td>${o.status==='Cancelled'?'<span class="status-badge cancelled">Cancelled</span>':`<div class="status-control"><span class="status-badge ${o.status.toLowerCase()}">${o.status}</span><select data-status-select="${o.id}" aria-label="Change order status">${allowed.map(s=>`<option value="${s}" ${s===o.status?'selected':''}>${s}</option>`).join('')}</select>${o.status!=='Delivered'?`<button class="cancel-order" data-status="${o.id}" data-next="Cancelled">Cancel order</button>`:''}</div>`}</td></tr>`}).join('')||'<tr><td colspan="5">No orders for this date.</td></tr>'}</tbody></table></section>`}
function productsView(){return `<div class="admin-heading"><h1>Products</h1></div><section class="admin-section"><h2>Add product detail</h2><form id="new-product" class="product-editor"><div class="editor-grid"><input name="name" placeholder="Product name" required><input name="tone" placeholder="Tone / slug" required><input name="priceNote" placeholder="Price note (optional)"></div><textarea name="description" placeholder="Product description, material, care, and fit notes"></textarea><label class="file-input">Product photos<input name="photos" type="file" accept="image/png,image/jpeg,image/webp" multiple required></label><div class="variant-editor"><b>First variant</b><div class="variant-fields"><input name="label" placeholder="Label e.g. Free Size" required><input name="fit" placeholder="Fit e.g. 80–135 lb" required><input name="price" type="number" placeholder="Price Ks" required></div></div><button>Add product</button></form></section><section class="admin-section"><h2>Catalog</h2>${products.map(p=>`<details class="catalog-card"><summary><span>${esc(p.name)}</span><small>${p.prices.length} variants · ${p.images.length} photos</small></summary><form class="price-product product-editor" data-edit-product><div class="product-row"><h3>Edit ${esc(p.name)}</h3><button type="button" data-delete="${esc(p.tone)}">Delete</button></div><input type="hidden" name="tone" value="${esc(p.tone)}"><div class="editor-grid"><input name="name" value="${esc(p.name)}" placeholder="Product name" required><input name="priceNote" value="${esc(p.priceNote||'')}" placeholder="Price note"><textarea name="description" placeholder="Product description">${esc(p.description||'')}</textarea></div><label class="file-input">Add photos<input name="photos" type="file" accept="image/png,image/jpeg,image/webp" multiple></label><div class="existing-photos"><b>Keep photos</b>${p.images.map((src,i)=>`<label><input type="checkbox" name="keepImage" value="${esc(src)}" checked><img src="${src}" alt="Photo ${i+1}"></label>`).join('')}</div><div class="variant-editor"><b>Variants</b>${p.prices.map((v,i)=>`<div class="variant-fields"><select name="group-${i}"><option ${v.group==='Free Size'?'selected':''}>Free Size</option><option ${v.group==='Plus Size'?'selected':''}>Plus Size</option></select><input name="label-${i}" value="${esc(v.label)}" placeholder="Label" required><input name="fit-${i}" value="${esc(v.fit)}" placeholder="Fit" required><input name="price-${i}" type="number" value="${amount(v.price)}" placeholder="Price" required></div>`).join('')}<div class="variant-fields"><select name="group-new"><option>Free Size</option><option>Plus Size</option></select><input name="label-new" placeholder="New variant label"><input name="fit-new" placeholder="New variant fit"><input name="price-new" type="number" placeholder="New price"></div></div><button>Save product details</button></form></details>`).join('')}</section>`}
function reportsView(){const revenue=orders.reduce((n,o)=>n+Number(o.total),0);return `<div class="admin-heading"><h1>Reports</h1></div><section class="stats"><div><small>Revenue</small><b>${money(revenue)}</b></div><div><small>Total orders</small><b>${orders.length}</b></div><div><small>Pending</small><b>${orders.filter(o=>o.status==='Pending').length}</b></div><div><small>Shipped</small><b>${orders.filter(o=>o.status==='Shipped').length}</b></div></section><section class="admin-section"><h2>Product demand</h2>${products.map(p=>`<div class="report-row"><span>${esc(p.name)}</span><b>${orders.reduce((n,o)=>n+o.items.filter(i=>i.tone===p.tone).reduce((x,i)=>x+i.quantity,0),0)} sold</b></div>`).join('')}</section>`}
function settingsView(){return `<div class="admin-heading"><h1>Settings</h1></div><section class="admin-section"><h2>Change passcode</h2><form id="change-pass" class="product-form"><input name="current" type="password" autocomplete="current-password" placeholder="Current passcode" required><input name="next" type="password" autocomplete="new-password" minlength="12" maxlength="128" placeholder="New passcode (12 characters minimum)" required><button>Update passcode</button><p class="form-error" role="alert"></p></form></section>`}
function loginSubmit(e:Event){e.preventDefault();api('/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({passcode:(document.querySelector('#passcode')as HTMLInputElement).value})}).then(async()=>{[products,orders]=await Promise.all([api<Product[]>('/products'),api<Order[]>('/admin/orders')]);isAdmin=true;render()}).catch(err=>document.querySelector('#login-error')!.textContent=err.message)}
async function status(id:string,value:string){await api(`/admin/orders/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:value})});orders=await api<Order[]>('/admin/orders');render()}
async function checkout(){if(!customerProfile)return notify('Sign in before placing an order');const items=[...cart],orderTotal=total();if(!items.length)return;const button=document.querySelector<HTMLButtonElement>('#checkout');if(button){button.disabled=true;button.textContent='Placing order…'}try{const r=await api<{id:string}>('/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items})});saveOrderId(r.id);cart=[];saveCart();render();invoiceModal(r.id,customerProfile.name,customerProfile.phone,`${customerProfile.deliveryAddress}, ${customerProfile.city}`,items,orderTotal)}catch(error){notify((error as Error).message);if(button){button.disabled=false;button.textContent='Place order'}}}
async function readFiles(form:HTMLFormElement){return Promise.all(Array.from((form.querySelector('[name="photos"]') as HTMLInputElement)?.files||[]).map(file=>new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file)})))}
async function createProduct(e:Event){e.preventDefault();const form=e.target as HTMLFormElement,d=new FormData(form),images=await readFiles(form);await api('/admin/products',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:d.get('name'),tone:d.get('tone'),description:d.get('description'),priceNote:d.get('priceNote'),images,prices:[{group:'Free Size',label:d.get('label'),fit:d.get('fit'),price:Number(d.get('price'))}]})});products=await api<Product[]>('/products');render()}
async function editProduct(e:Event){e.preventDefault();const form=e.target as HTMLFormElement,submit=Array.from(form.querySelectorAll<HTMLButtonElement>('button')).find(button=>button.type!=='button'),original=submit?.textContent;if(submit){submit.disabled=true;submit.textContent='Saving…'}try{const d=new FormData(form),tone=String(d.get('tone')),prices=products.find(p=>p.tone===tone)?.prices.map((_,i)=>({group:d.get(`group-${i}`),label:d.get(`label-${i}`),fit:d.get(`fit-${i}`),price:Number(d.get(`price-${i}`))}))||[];const newLabel=String(d.get('label-new')||'').trim();if(newLabel)prices.push({group:d.get('group-new'),label:newLabel,fit:d.get('fit-new'),price:Number(d.get('price-new'))});const images=[...d.getAll('keepImage').map(String),...await readFiles(form)];if(!images.length)throw Error('Keep at least one photo');await api(`/admin/products/${encodeURIComponent(tone)}/cover`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({fit:d.get('coverFit')||'cover',position:d.get('coverPosition')||'center',zoom:Number(d.get('coverZoom')||100)})});await api(`/admin/products/${encodeURIComponent(tone)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:d.get('name'),description:d.get('description'),priceNote:d.get('priceNote'),images,prices})});products=await api<Product[]>('/products');notify('Product details saved and storefront refreshed');render()}catch(error){notify(`Save failed: ${(error as Error).message}`);if(submit){submit.disabled=false;submit.textContent=original||'Save product details'}}}
async function deleteProduct(tone:string){if(!confirm('Delete this product?'))return;if(!confirm('Confirm again: permanently delete this product?'))return;await api(`/admin/products/${encodeURIComponent(tone)}`,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm:'DELETE'})});products=await api<Product[]>('/products');render()}
async function changePass(e:Event){e.preventDefault();const form=e.target as HTMLFormElement,button=form.querySelector<HTMLButtonElement>('button')!,error=form.querySelector<HTMLElement>('.form-error')!,d=new FormData(form);button.disabled=true;error.textContent='';try{await api('/admin/passcode',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({current:d.get('current'),next:d.get('next')})});form.reset();notify('Passcode updated. Other admin sessions have been signed out.')}catch(cause){error.textContent=(cause as Error).message}finally{button.disabled=false}}
async function findOrder(){const id=(document.querySelector('#order-number')as HTMLInputElement).value.trim();if(!id)return;try{const o=await api<Order & {phone:string;address:string;cancelRequested:boolean}>(`/orders/${id}`);document.querySelector('#order-result')!.innerHTML=`<p>Order #${o.id}: ${esc(o.status)}</p><p>${esc(o.customer)} · ${esc(o.address)}</p>${o.status==='Pending'?`<button id="cancel-order">Request cancellation</button>`:''}`;document.querySelector('#cancel-order')?.addEventListener('click',async()=>{await api(`/orders/${id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:'cancel',message:'Customer requested cancellation'})});alert('Cancellation requested')})}catch{document.querySelector('#order-result')!.textContent='Order not found'}}
const localeObserver=new MutationObserver(()=>{if(document.querySelector('header'))bindLocaleToggle()});localeObserver.observe(document.querySelector('#app')!,{childList:true});
function cachedCatalog():Product[]|null{try{const saved=JSON.parse(localStorage.getItem('yc_catalog_cache')||'null') as {time?:number;products?:Product[]}|null;return saved?.time&&Date.now()-saved.time<10*60*1000&&Array.isArray(saved.products)?saved.products:null}catch{return null}}
async function start(){
  if(developerRoute()){try{isDeveloper=(await api<{authenticated:boolean}>('/developer/session')).authenticated}catch{isDeveloper=false}render();return}
  if(adminRoute()){render();try{isAdmin=(await api<{authenticated:boolean}>('/admin/session')).authenticated;if(isAdmin)[products,orders]=await Promise.all([api<Product[]>('/products'),api<Order[]>('/admin/orders')]);render()}catch{return}return}
  const initialCatalog=cachedCatalog();
  if(initialCatalog&&(location.pathname==='/'||location.pathname.startsWith('/product/'))){products=initialCatalog;render();bindLocaleToggle()}
  else if(location.pathname==='/'){render();bindLocaleToggle();document.querySelector('#catalog')!.innerHTML='<p role="status">Loading products…</p>'}
  const catalogRequest=api<Product[]>('/products').catch(()=>null);
  const sessionRequest=api<{authenticated:boolean;profile:CustomerProfile|null}>('/customer/session').catch(()=>null);
  const providersRequest=location.pathname.startsWith('/signup')||location.pathname==='/login'?api<{telegram:boolean;tiktok:boolean}>('/customer/providers').catch(()=>null):Promise.resolve(null);
  try{
    if((await api<{maintenance:boolean}>('/store/status')).maintenance){maintenanceScreen();return}
    const cached=cachedCatalog();
    if(cached){products=cached;if(location.pathname==='/'||location.pathname.startsWith('/product/'))render()}
    const catalog=await catalogRequest;
    if(!catalog&&!cached){document.querySelector('#app')!.innerHTML='<main class="empty">Store unavailable</main>';return}
    if(catalog){products=catalog;try{const value=JSON.stringify({time:Date.now(),products:catalog});if(value.length<2_000_000)localStorage.setItem('yc_catalog_cache',value)}catch{}}
    render();
    const [session,providers]=await Promise.all([sessionRequest,providersRequest]);
    if(session)customerProfile=session.profile;
    if(providers)socialProviders=providers;
    if(session?.profile||providers)render();
  }catch{if(products.length){render();return}document.querySelector('#app')!.innerHTML='<main class="empty">Store unavailable</main>'}
}start();
